const detail = $input.first().json;
const input = $('When called').first().json;
const product_names_lower = Array.from(new Set((detail.products || []).map(p => (p.name || '').toLowerCase()).filter(Boolean)));
return [{ json: {
  detail,
  location_key: input.location_key,
  access_token: input.access_token,
  product_names_lower
}}];

const detail = $('Pin Context').first().json.detail;
const location_key = $('Pin Context').first().json.location_key;
const pluMapRows = $('Load Targeted PLU Map').all();
const lsCatalogRows = $('Load Targeted Catalog').all();

const pluByName = {};
for (const r of pluMapRows) { if (r.json.takeaway_name_lower) pluByName[r.json.takeaway_name_lower] = r.json.ls_plu; }

const lsCatalogByName = {};
for (const r of lsCatalogRows) {
  const lower = r.json.name_lower; if (!lower) continue;
  if (!lsCatalogByName[lower]) lsCatalogByName[lower] = [];
  lsCatalogByName[lower].push(r.json.sku);
}

function resolvePlu(productName) {
  const nameLower = (productName || '').toLowerCase();
  if (pluByName[nameLower]) return pluByName[nameLower];
  const matches = lsCatalogByName[nameLower] || [];
  if (matches.length === 1) return matches[0];
  if (matches.length > 1) return 'AMBIGUOUS:' + (productName || 'unknown').slice(0, 80);
  return 'UNMAPPED:' + (productName || 'unknown').slice(0, 80);
}

function mapPayment(pt) {
  const map = {'online':{method:'card_online',status:'paid'},'creditcard':{method:'card_online',status:'paid'},'visa':{method:'card_online',status:'paid'},'mastercard':{method:'card_online',status:'paid'},'takeawayPay':{method:'card_online',status:'paid'},'jetpay':{method:'card_online',status:'paid'},'cash':{method:'cash',status:'pending'},'pinAtHome':{method:'bancontact',status:'pending'},'home_debitcard':{method:'bancontact',status:'pending'},'home_creditcard':{method:'card_online',status:'pending'},'mealVoucher':{method:'voucher',status:'pending'},'meal_voucher':{method:'voucher',status:'paid'},'voucher':{method:'voucher',status:'paid'},'giftCard':{method:'voucher',status:'paid'},'cheque':{method:'other',status:'pending'},'accountcredit':{method:'other',status:'paid'},'debitcard':{method:'bancontact',status:'paid'}};
  return map[pt] || { method:'card_online', status:'paid' };
}
function euroToCents(n){return Math.round(Number(n||0)*100);}

const products = detail.products || [];
const items = products.map(p => {
  const modifiers = (p.specifications||[]).map(s => ({plu:'', name:s.name||'', unit_price_cents:euroToCents(s.amount)}));
  const item = { plu: resolvePlu(p.name), name: p.name, qty: p.quantity||1, unit_price_cents: euroToCents(p.amount), modifiers };
  if (p.remarks) item.notes = String(p.remarks);
  return item;
});

const c = detail.customer || {};
const isDelivery = detail.delivery_type === 'delivery';
// JET extras: c.extra = ["Floor: 001", ...] (bus/verdiep) -> line2; c.company_name is
// free text customers use for delivery instructions or names -> keep in notes.
const line1Norm = [c.street, c.street_number].filter(Boolean).join(' ').toLowerCase().replace(/\s+/g, '');
const extraParts = (Array.isArray(c.extra) ? c.extra : [])
  .map(v => String(v).trim()).filter(Boolean)
  .filter(v => !line1Norm.includes(v.toLowerCase().replace(/\s+/g, ''))); // skip if already in line1
const extraLine = extraParts.length ? extraParts.join(', ') : null;
const addr = isDelivery ? { line1:[c.street,c.street_number].filter(Boolean).join(' '), line2: extraLine, postal_code:c.postcode||'', city:c.city||'', country:'BE', lat:null, lng:null } : null;
const notesParts = [detail.remarks, c.company_name].map(v => (v == null ? '' : String(v).trim())).filter(Boolean);
const customer = { name: c.full_name || 'Takeaway Customer', email: null, phone: c.phone_number || null, address: addr, notes: notesParts.length ? notesParts.join(' | ') : null };

const pay = mapPayment(detail.payment_type);
const totalCents = euroToCents(detail.customer_total != null ? detail.customer_total : detail.restaurant_total);
const baseCents = Math.round(totalCents / 1.12);
const vatCents = totalCents - baseCents;
const vat_lines = [{ rate_bp:1200, base_cents:baseCents, vat_cents:vatCents }];

const external_ref = 'Takeaway - ' + detail.public_reference;
const canonical = { schema_version:'1.1', source:'takeaway', external_ref, location_key, order_type: isDelivery?'delivery':'pickup', status:'received', customer, items, payment:{method:pay.method,status:pay.status,total_cents:totalCents,currency:detail.currency||'EUR'}, vat_lines };
const product_names = Array.from(new Set(products.map(p => p.name).filter(Boolean)));

return [{ json: { detail_id: detail.id, external_ref, location_key, is_delivery: isDelivery, order_type: canonical.order_type, canonical, raw_payload: detail, product_names } }];

