const norm = $('Normalize Order').first().json;
const items = norm.canonical.items || [];
const unmapped = items.filter(i => String(i.plu||'').startsWith('UNMAPPED:') || String(i.plu||'').startsWith('AMBIGUOUS:')).length;
return [{ json: { external_ref: norm.external_ref, status: 'ok', ls_plu_unmapped_count: unmapped }}];

// Accept-failure classifier. JET's own portal treats these statuses distinctly
// (bundle error handler): 403 reason=pin_required, 403 message="Wrong status
// transition!", 422, 404, 500. We mirror that, and we capture the FULL response
// body so one failure is enough to diagnose (2026-08-07 cost two evenings because
// continueOnFail swallowed the body).
const resp = $input.first().json ?? {};
const detail = $('Pin Context').first().json.detail;
const env = $('When called').first().json;

const code = Number(resp.statusCode ?? resp.error?.status ?? 0);
const body = resp.body ?? resp.error?.message ?? null;
const bodyStr = typeof body === 'string' ? body : JSON.stringify(body ?? null);
const ok = code >= 200 && code < 300;

// JET returns {"reason":"pin_required"} or {"message":"Wrong status transition!"}
let reason = '';
try {
  const parsed = typeof body === 'string' ? JSON.parse(body) : body;
  reason = parsed?.reason || parsed?.message || '';
} catch (e) { reason = String(bodyStr).slice(0, 120); }

// Only a genuinely NEW order that we failed to accept is an incident. If the order
// already left 'new', staff (or an earlier run) accepted it — expected, not a failure.
// FAIL-CLOSED: an unreadable/missing status must ALARM, never stay silent. The old
// test (detail.status === 'new') went quiet whenever the detail fetch returned
// something unexpected — the one case where we most need to hear about it.
let statusFetched = (detail && typeof detail.status === 'string') ? detail.status : null;
// 2026-09-13 17:50-18:55: JET answered 500 / timed out on six accepts but had processed
// every one of them (confirmed_at == our push minute, all printed). A non-2xx or timeout
// is therefore NOT proof of failure. Ask JET once more before alarming: if the order has
// left 'new', the accept landed and the alarm would be false. Only a still-'new' order
// (or an unreachable re-check) is an incident.
let recheck = null;
if (!ok && detail && detail.id) {
  try {
    const again = await this.helpers.httpRequest({
      url: 'https://live-orders-api.takeaway.com/api/orders/' + detail.id,
      headers: { Authorization: 'Bearer ' + env.access_token, Accept: 'application/json',
                 'X-Requested-With': 'XMLHttpRequest', 'X-Timezone': 'Europe/Brussels' },
      json: true, timeout: 8000 });
    if (again && typeof again.status === 'string') { recheck = again.status; statusFetched = again.status; }
  } catch (e) { recheck = 'RECHECK_FAILED: ' + String(e.message || e).slice(0, 80); }
}
const alreadyHandled = statusFetched !== null && statusFetched !== 'new';
const alert = !ok && !alreadyHandled;

function lit(v) { return v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'"; }

let sql = 'SELECT 1';
if (alert) {
  const err = JSON.stringify({
    message: 'JET accept failed (HTTP ' + code + '): ' + String(reason).slice(0, 200),
    stage: 'takeaway_accept',
    http_status: code,
    jet_reason: String(reason).slice(0, 200),
    response_body: String(bodyStr).slice(0, 800),
    request_body: JSON.stringify($('Build Accept Body').first().json.accept_body ?? null),
    order_status_fetched: statusFetched ?? 'UNKNOWN',
    recheck_status: recheck,
    delivery_type: detail.delivery_type,
    detail_id: detail.id,
    runbook: code === 403 && /pin/i.test(reason)
      ? 'JET PIN protection is enabled on this restaurant — accept on the tablet and disable the PIN, or implement X-pin-token.'
      : 'Accept the order in the JET partner hub NOW, then compare request_body against docs/API Docs/TAKEAWAY-ACCEPT-CONTRACT.md',
  });
  sql = "INSERT INTO public.dlq_alerts (queue_name, msg_id, external_ref, source, location_key, last_error, attempt_count) VALUES ('takeaway_accept', "
    + Number(detail.id) + ", " + lit('Takeaway - ' + detail.public_reference) + ", 'takeaway', "
    + lit(env.location_key) + ", " + lit(err) + "::jsonb, 1) ON CONFLICT (queue_name, msg_id) DO NOTHING";
}
return [{ json: { sql, accept_ok: ok, http_status: code, jet_reason: reason, alerted: alert, recheck_status: recheck, accepted_despite_error: (!ok && alreadyHandled) } }];

// Build the JET confirm-order payload.
// Contract: docs/API Docs/TAKEAWAY-ACCEPT-CONTRACT.md (derived from JET's own portal
// bundle + 10 production rows accepted by staff).
//   food_preparation_duration : integer MINUTES
//   delivery_time_duration    : integer MINUTES; 0 (NOT null) for pickup. Proven by
//     JET's own accept hook, useConfirmTakeawayOrder.ts, recovered from the Orders
//     chunk on 2026-08-09:
//       useState(order.is_pickup ? 0 : restaurant.average_delivery_duration)
//   estimated_delivery_time   : the portal ALWAYS posts null here, because
//     can_change_confirmed_time_of_order() forbids setting a time while the order is
//     'new'. JET then derives restaurant_estimated_delivery_time = confirmed_at +
//     prep + delivery (verified exactly on 7 production rows).
const d = $('Pin Context').first().json.detail;
const isDelivery = d.delivery_type === 'delivery';

const accept_body = {
  food_preparation_duration: 15,
  delivery_time_duration: isDelivery ? 25 : 0,
  estimated_delivery_time: null,
};
return [{ json: { accept_body, detail_id: d.id } }];
